#include <iostream>

int main() {
    int number = 0;
    if (!(std::cin >> number)) {
        return 0;
    }

    std::cout << std::boolalpha;

    bool div2 = (number % 2 == 0);
    bool div3 = (number % 3 == 0);
    bool div2And3 = div2 && div3;
    bool div2Or3 = div2 || div3;
    bool div2Or3NotBoth = (div2 || div3) && !(div2 && div3);

    std::cout << "Divisible by 2 and 3: " << div2And3 << "\n";
    std::cout << "Divisible by 2 or 3: " << div2Or3 << "\n";
    std::cout << "Divisible by 2 or 3 but not both: " << div2Or3NotBoth << "\n";

    // Verify De Morgan's Law equivalence: !(div2 && div3) == (!div2 || !div3)
    bool deMorganCheck = (!(div2 && div3) == (!div2 || !div3));
    std::cout << "De Morgan verified: " << deMorganCheck << "\n";

    return 0;
}

#include <iostream>

int main() {
    double x = 0, y = 0, z = 0;
    if (!(std::cin >> x >> y >> z)) {
        return 0;
    }

    // Demonstrating evaluation identical to Check Point 3.27
    std::cout << "(x < y && y < z) is " << (x < y && y < z) << "\n";
    std::cout << "(x < y || y < z) is " << (x < y || y < z) << "\n";
    std::cout << "!(x < y) is " << !(x < y) << "\n";
    std::cout << "(x + y < z) is " << (x + y < z) << "\n";
    std::cout << "(x + y > z) is " << (x + y > z) << "\n";

    return 0;
}
